import { Component, h, State } from '@stencil/core';

@Component({
  tag: 'std-banner-ads',
  styleUrl: 'std-banner-ads.css',
  shadow: true
})
export class StdBannerAdsComponent {
  //Validar si es necesario a futuro esta Props para Ocultar en lg
  //@Prop() status: boolean;

  @State() isOpen: boolean;
  @State() label: string = 'Mostrar banner';
  @State() icon: string = 'chevron-down';

  toggleCollapse(): void {
    this.isOpen = !this.isOpen;
    this.label = this.isOpen ? 'Ocultar banner' : 'Mostrar banner';
    this.icon = this.isOpen ? 'chevron-up' : 'chevron-down';
  }

  render() {
    return (
      <div class={`css-collapse js-collapse hidden lg:flex flex-col gap-2 ${this.isOpen ? 'is-open' : ''}`}>
        <div class="js-collapse-header flex justify-end" onClick={() => this.toggleCollapse()}>
          <div class="hidden-collapse block">
            <std-button size="s" type="tertiary" label={this.label} icon={this.icon}></std-button>
          </div>
        </div>
        <div class="js-collapse-body css-collapse-body hidden">
          <slot />
        </div>
      </div>
    );
  }
}
